395	        if (!hasPlan()) {
396	            return List.of();
397	        }
398	        MathContext mc = MathContext.DECIMAL128;
399	        BigDecimal principal = total(taxRate);
400	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
401	        int n = instalments;
402	        BigDecimal payment;
403	        if (i.signum() == 0) {
404	            payment = principal.divide(BigDecimal.valueOf(n), 2, RoundingMode.HALF_UP);
405	        } else {
