407	            payment = principal.multiply(i).multiply(growth)
408	                    .divide(growth.subtract(BigDecimal.ONE), mc).setScale(2, RoundingMode.HALF_UP);
409	        }
410	        List<Instalment> schedule = new ArrayList<>(n);
411	        BigDecimal balance = principal.setScale(2, RoundingMode.HALF_UP);
412	        for (int k = 1; k <= n; k++) {
413	            BigDecimal interest = balance.multiply(i).setScale(2, RoundingMode.HALF_UP);
414	            BigDecimal paid = k == n ? balance.add(interest) : payment;
415	            BigDecimal repaid = paid.subtract(interest);
416	            balance = balance.subtract(repaid);
417	            LocalDate due = issueDate == null ? null : issueDate.plusMonths(k);
418	            schedule.add(new Instalment(k, due, paid, interest, repaid, balance));
419	        }
420	        return schedule;
