552	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
553	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
554	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
555	        BigDecimal sum = BigDecimal.ZERO;
556	        for (Part p : inOrder) {
557	            sum = sum.add(p.amount());
558	            if (sum.signum() > 0 && total.subtract(sum).compareTo(WRITE_OFF_LIMIT) < 0) {
559	                return p.on();
560	            }
561	        }
562	        return null;
563	    }
564	
565	    /**
566	     * What is still due once the given amount has been paid: the grand total less it, less what credit
567	     * notes have credited, less the retention still held, less anything written off — so nothing once
568	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
569	     */
570	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
571	        if (isCreditNote()) {
572	            return BigDecimal.ZERO.setScale(2);
573	        }
574	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
575	    }
576	
577	    /**
578	     * What is written off once the given amount has been paid: when payments leave less than
579	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
580	     */
581	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
582	        BigDecimal left = payable(taxRate).subtract(paid);
583	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && left.compareTo(WRITE_OFF_LIMIT) < 0
584	                ? left.setScale(2, RoundingMode.HALF_UP)
585	                : BigDecimal.ZERO.setScale(2);
586	    }
587	
588	    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
589	    public BigDecimal minimumPart(BigDecimal taxRate) {
590	        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(2, RoundingMode.HALF_UP);
591	    }
592	
593	    /**
594	     * Whether paying the amount on top of what was already paid is too small a part payment: under
595	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
596	     */
597	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
598	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
599	    }
600	
601	    /** Adds a line to the end of the invoice. */
602	    public void addLine(InvoiceLine line) {
603	        lines.add(line);
604	    }
605	
606	    /** Whether the invoice has the line with the given id. */
607	    public boolean hasLine(Long lineId) {
608	        return lines.stream().anyMatch(l -> lineId.equals(l.getId()));
609	    }
610	
611	    /**
612	     * Removes the line with the given id; whether the invoice had it. Refused when what is left would
613	     * be less than a fixed discount on the invoice.
614	     */
615	    public boolean removeLine(Long lineId) {
616	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
617	        if (line == null) {
618	            return false;
619	        }
620	        BigDecimal left = subtotal().subtract(line.amount());
621	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
622	            throw new InvoiceRejectedException("This line cannot be removed: the $"
623	                    + left.setScale(2).toPlainString() + " left would be less than the $"
624	                    + discountAmount.setScale(2).toPlainString() + " discount.");
625	        }
626	        lines.remove(line);
627	        return true;
628	    }
629	
630	    /**
631	     * Changes the line with the given id to the given values; whether the invoice had it. Refused when
632	     * the subtotal would then be less than a fixed discount on the invoice.
633	     */
634	    public boolean updateLine(Long lineId, String description, BigDecimal qty, BigDecimal unitPrice,
635	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
636	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
637	        if (line == null) {
638	            return false;
639	        }
640	        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount();
641	        BigDecimal left = subtotal().subtract(line.amount()).add(changed);
642	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
643	            throw new InvoiceRejectedException("This line cannot be changed: the $"
644	                    + left.setScale(2).toPlainString() + " subtotal would be less than the $"
645	                    + discountAmount.setScale(2).toPlainString() + " discount.");
646	        }
647	        line.update(description, qty, unitPrice, taxExempt, discountPct, taxRate);
648	        return true;
649	    }
650	
651	    /**
652	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
653	     * matches what a client gets by adding up the lines shown.
654	     */
655	    public BigDecimal subtotal() {
656	        return lines.stream().map(InvoiceLine::amount)
657	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
658	    }
659	
660	    /**
661	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
662	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
663	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
664	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
665	     */
666	    public BigDecimal discount() {
667	        BigDecimal discount = discountAmount.signum() > 0
668	                ? discountAmount.min(subtotal()).setScale(2, RoundingMode.HALF_UP)
669	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(2, RoundingMode.DOWN);
670	        if (discountCap == null) {
671	            return discount;
672	        }
673	        BigDecimal lineDiscounts = lines.stream().map(InvoiceLine::discount)
674	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
675	        BigDecimal left = discountCap.setScale(2, RoundingMode.HALF_UP).subtract(lineDiscounts).max(BigDecimal.ZERO.setScale(2));
676	        return discount.min(left);
677	    }
678	
679	    /**
680	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
681	     * proportion to the line amounts: each line first gets the whole cents of its exact share
682	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
683	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
684	     * equal amounts too to the lower line id. The shares add up to the discount.
685	     */
686	    public List<BigDecimal> discountShares() {
687	        BigInteger discountCents = discount().movePointRight(2).toBigIntegerExact();
688	        BigInteger subtotalCents = subtotal().movePointRight(2).toBigIntegerExact();
689	        int n = lines.size();
690	        BigInteger[] shares = new BigInteger[n];
691	        BigInteger[] leftovers = new BigInteger[n];
692	        BigInteger given = BigInteger.ZERO;
693	        for (int i = 0; i < n; i++) {
694	            if (subtotalCents.signum() == 0) {
695	                shares[i] = BigInteger.ZERO;
696	                leftovers[i] = BigInteger.ZERO;
697	            } else {
698	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
699	                // as denominator, so the remainders compare as the fractions do.
700	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount().movePointRight(2).toBigIntegerExact())
701	                        .divideAndRemainder(subtotalCents);
702	                shares[i] = qr[0];
703	                leftovers[i] = qr[1];
704	            }
705	            given = given.add(shares[i]);
706	        }
707	        List<Integer> order = new ArrayList<>();
708	        for (int i = 0; i < n; i++) {
709	            order.add(i);
710	        }
711	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
712	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount()).reversed())
713	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
714	        int left = discountCents.subtract(given).intValueExact();
715	        for (int k = 0; k < left; k++) {
716	            int i = order.get(k);
717	            shares[i] = shares[i].add(BigInteger.ONE);
718	        }
719	        List<BigDecimal> result = new ArrayList<>(n);
720	        for (BigInteger share : shares) {
721	            result.add(new BigDecimal(share, 2));
722	        }
723	        return result;
724	    }
725	
726	    /**
727	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
728	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
729	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
730	     */
731	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
732	        List<BigDecimal> shares = discountShares();
733	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
734	        for (int i = 0; i < lines.size(); i++) {
735	            InvoiceLine line = lines.get(i);
736	            taxes.add(clientTaxExempt || line.isTaxExempt() ? BigDecimal.ZERO.setScale(2)
737	                    : line.amount().subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
738	                            .setScale(2, RoundingMode.HALF_UP));
739	        }
740	        return taxes;
741	    }
742	
743	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
744	    public BigDecimal tax(BigDecimal taxRate) {
745	        return lineTaxes(taxRate).stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
746	    }
747	
748	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
749	    public BigDecimal total(BigDecimal taxRate) {
750	        return subtotal().subtract(discount()).add(tax(taxRate));
751	    }
752	}
