208	     * payment refuses it.
209	     */
210	    @Transactional
211	    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
212	            BigDecimal discountCap, String discountReason) {
213	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
214	        found.ifPresent(invoice -> {
215	            if (invoice.isCreditNote()) {
216	                throw new InvoiceRejectedException("A credit note has no discount.");
217	            }
218	            boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
219	            if (discountAmount != null) {
