238	    /**
239	     * Sets a draft's due date by hand, kept when it is sent; empty if no such invoice. A date before
240	     * the issue date or more than {@link Invoice#MAX_DUE_DAYS} days after it is refused, as is any
241	     * invoice that is not a draft.
242	     */
243	    @Transactional
244	    public Optional<Invoice> setDueDate(Long invoiceId, LocalDate dueDate) {
245	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
246	        found.ifPresent(invoice -> {
247	            if (!invoice.isDraft()) {
248	                throw new InvoiceRejectedException("Only a draft's due date can be set.");
249	            }
250	            invoice.setDueDate(dueDate);
251	            invoices.saveAndFlush(invoice);
252	        });
