279	    /**
280	     * Spreads a draft over the number of monthly instalments at the annual interest rate; empty if no
281	     * such invoice. Both have already been checked; any invoice that is not a draft, a credit note, or
282	     * one holding back retention is refused.
283	     */
284	    @Transactional
285	    public Optional<Invoice> setPlan(Long invoiceId, int instalments, BigDecimal instalmentRate) {
286	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
287	        found.ifPresent(invoice -> {
288	            if (invoice.isCreditNote()) {
289	                throw new InvoiceRejectedException("A credit note cannot be spread over instalments.");
290	            }
291	            if (!invoice.isDraft()) {
292	                throw new InvoiceRejectedException("Only a draft can be spread over instalments.");
293	            }
294	            if (invoice.getRetentionPct().signum() > 0) {
295	                throw new InvoiceRejectedException("An invoice holding back retention cannot also be spread over instalments.");
296	            }
297	            invoice.setPlan(instalments, instalmentRate);
298	            invoices.saveAndFlush(invoice);
299	        });
300	        return found;
301	    }
