303	    /**
304	     * Releases the retention held back on a sent invoice today, adding it to the amount due (falling
305	     * due {@link Invoice#RETENTION_DUE_DAYS} days later), and records it in the audit; empty if no such
306	     * invoice. Refused while anything else is still due, or when there is no retention held to release.
307	     */
308	    @Transactional
309	    public Optional<Invoice> releaseRetention(Long invoiceId) {
310	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
311	        found.ifPresent(invoice -> {
312	            if (invoice.isDraft() || invoice.isVoid() || invoice.isCreditNote()) {
313	                throw new InvoiceRejectedException("Retention can only be released on a sent invoice.");
314	            }
315	            BigDecimal rate = taxRate.percent();
316	            BigDecimal held = invoice.retentionHeld(rate);
317	            if (held.signum() <= 0) {
318	                throw new InvoiceRejectedException("There is no retention held to release.");
319	            }
320	            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), rate);
321	            if (due.signum() > 0) {
322	                throw new InvoiceRejectedException("The retention can only be released once nothing else is due; $"
323	                        + due.setScale(2, RoundingMode.HALF_UP).toPlainString() + " is still due.");
324	            }
325	            invoice.releaseRetention(today.date());
326	            invoices.saveAndFlush(invoice);
327	            audit.record("RETENTION_RELEASED id=" + invoice.getId() + " amount=" + held.toPlainString());
328	        });
329	        return found;
330	    }
