332	    /**
333	     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
334	     * back to draft, to be sent again; an invoice with any payment is refused with the message.
335	     * Whether it went back to draft.
336	     */
337	    private boolean reopenForChange(Invoice invoice, String refusal) {
338	        if (invoice.isDraft()) {
339	            return false;
340	        }
341	        if (invoice.isVoid()) {
342	            throw new InvoiceRejectedException("A void invoice cannot be changed.");
343	        }
344	        if (invoice.isCreditNote()) {
345	            throw new InvoiceRejectedException("An issued credit note cannot be changed.");
346	        }
347	        if (invoice.hasCreditNotesIssued()) {
348	            throw new InvoiceRejectedException("An invoice with an issued credit note cannot be changed.");
349	        }
350	        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
351	            throw new InvoiceRejectedException(refusal);
352	        }
353	        invoice.reopen();
354	        return true;
355	    }
