357	    /**
358	     * Sends a draft invoice, issuing it today and making it due on the client's terms (or keeping a due
359	     * date set by hand), and records it in the audit; empty if no such invoice. An invoice already
360	     * sent, with no lines, whose discount needs a reason but has none, or whose due date set by hand is
361	     * before today, is refused.
362	     */
363	    @Transactional
364	    public Optional<Invoice> send(Long invoiceId) {
365	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
366	        found.ifPresent(invoice -> {
367	            if (invoice.isVoid()) {
368	                throw new InvoiceRejectedException("A void invoice cannot be sent.");
369	            }
370	            if (!invoice.isDraft()) {
371	                throw new InvoiceRejectedException("This invoice has already been sent.");
372	            }
373	            if (invoice.getLines().isEmpty()) {
374	                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
375	            }
376	            if (invoice.isCreditNote()) {
377	                String refusal = creditNoteRefusal(invoice);
378	                if (refusal != null) {
379	                    throw new InvoiceRejectedException(refusal);
380	                }
381	                issue(invoice);
382	                return;
383	            }
384	            if (invoice.discountLacksReason()) {
385	                throw new InvoiceRejectedException(
386	                        "The discount is more than 20% of the subtotal; give it a reason before sending the invoice.");
387	            }
388	            if (invoice.dueDatePassedBy(today.date())) {
389	                throw new InvoiceRejectedException("The due date (" + invoice.getDueDate()
390	                        + ") is already past; set a later due date before sending the invoice.");
391	            }
392	            markSent(invoice);
393	        });
394	        return found;
395	    }
