397	    /**
398	     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
399	     * would; drafts with no lines, whose discount needs a reason but has none, or whose due date set by
400	     * hand is already past, stay drafts.
401	     */
402	    @Transactional
403	    public void sendAllDrafts(Long clientId) {
404	        invoices.findByClientIdOrderByIdAsc(clientId).stream()
405	                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason()
406	                        && !invoice.dueDatePassedBy(today.date()))
407	                .forEach(invoice -> {
408	                    if (!invoice.isCreditNote()) {
409	                        markSent(invoice);
410	                    } else if (creditNoteRefusal(invoice) == null) {
411	                        issue(invoice);
412	                    }
413	                });
414	    }
