416	    /**
417	     * Why the draft credit note cannot be issued, or null when it can: its original must be a sent
418	     * invoice (not void).
419	     */
420	    private String creditNoteRefusal(Invoice note) {
421	        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElse(null);
422	        if (original == null || original.isDraft() || original.isVoid()) {
423	            return "The invoice this credits is not a sent invoice, so the credit note cannot be issued.";
424	        }
425	        return null;
426	    }
427	
428	    /**
429	     * Issues the draft credit note today and records it in the audit: its grand total comes off what
430	     * its original still owes, then the retention it holds back; any rest is held on the client's
431	     * account as a credit payment dated today, also recorded in the audit.
432	     */
433	    private void issue(Invoice note) {
434	        BigDecimal rate = taxRate.percent();
435	        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElseThrow();
436	        // Read again what it has been credited: another credit note may just have been issued against it.
437	        entityManager.refresh(original);
438	        BigDecimal total = note.total(rate);
439	        BigDecimal[] taken = original.creditTaken(total, paid(List.of(original)).get(original.getId()), rate);
440	        note.markIssued(today.date(), rate, taken[0], taken[1]);
441	        invoices.saveAndFlush(note);
442	        audit.record("CREDIT_NOTE_ISSUED id=" + note.getId() + " number=" + note.number() + " invoice="
443	                + note.getCreditOf() + " total=" + total.toPlainString());
444	        BigDecimal rest = total.subtract(taken[0]);
445	        if (rest.signum() > 0) {
446	            recordCreditHeld(payments.saveAndFlush(Payment.fromCreditNote(note, rest)));
447	        }
448	    }
449	
450	    /**
451	     * Issues the draft today, due on the client's terms, and records it in the audit; then uses the
452	     * client's credit on it (see {@link #applyCredit}), unless it is spread over instalments, whose
453	     * schedule is dated from the new issue date.
454	     */
455	    private void markSent(Invoice invoice) {
456	        LocalDate issued = today.date();
457	        invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
458	        invoices.saveAndFlush(invoice);
459	        audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + invoice.number()
460	                + " total=" + invoice.total(taxRate.percent()).toPlainString());
461	        if (!invoice.hasPlan()) {
462	            applyCredit(invoice);
463	        }
464	    }
465	
466	    /**
467	     * Uses the client's credit on the invoice just sent, up to what it has due: the oldest payment's
468	     * credit first (lower id first on the same date), each part applied today and recorded in the audit.
469	     */
470	    private void applyCredit(Invoice invoice) {
471	        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
472	        LocalDate now = today.date();
473	        boolean used = false;
474	        for (Payment payment : payments.findForClient(invoice.getClientId())) {
475	            if (due.signum() <= 0) {
476	                break;
477	            }
478	            BigDecimal credit = payment.credit();
479	            if (credit.signum() <= 0) {
480	                continue;
481	            }
482	            BigDecimal part = credit.min(due);
483	            payment.apply(invoice.getId(), part, now);
484	            payments.saveAndFlush(payment);
485	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
486	                    + part.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
487	            due = due.subtract(part);
488	            used = true;
489	        }
490	        if (used) {
491	            recordWriteOff(invoice);
492	        }
493	    }
494	
495	    /**
496	     * Records a deposit of the amount on the date from the client: the whole amount is held on the
497	     * client's account as credit, applied to no invoice, and recorded in the audit; empty if no such
498	     * client. The amount has already been checked; a date after today is refused.
499	     */
500	    @Transactional
501	    public Optional<Payment> recordDeposit(Long clientId, BigDecimal amount, LocalDate date) {
502	        if (clients.findById(clientId).isEmpty()) {
503	            return Optional.empty();
504	        }
505	        LocalDate now = today.date();
506	        if (date.isAfter(now)) {
507	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
508	        }
509	        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date));
510	        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
511	                + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
512	        return Optional.of(payment);
513	    }
514	
515	    /**
516	     * Refunds the amount of the client's unused credit on the date: the oldest payment's credit first
517	     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
518	     * such client. The amount has already been checked; a date after today or before a payment it
519	     * would come from, or an amount more than the client's credit, is refused.
520	     */
521	    @Transactional
522	    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
523	        if (clients.findById(clientId).isEmpty()) {
524	            return Optional.empty();
525	        }
526	        LocalDate now = today.date();
527	        if (date.isAfter(now)) {
528	            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
529	        }
530	        List<Payment> from = new ArrayList<>();
531	        List<BigDecimal> parts = new ArrayList<>();
532	        BigDecimal left = amount;
533	        BigDecimal credit = BigDecimal.ZERO;
534	        for (Payment payment : payments.findForClient(clientId)) {
535	            BigDecimal unused = payment.credit();
536	            if (unused.signum() <= 0) {
537	                continue;
538	            }
539	            credit = credit.add(unused);
540	            if (left.signum() <= 0) {
541	                continue;
542	            }
543	            BigDecimal part = unused.min(left);
544	            if (date.isBefore(payment.getDate())) {
545	                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
546	                        + payment.getDate() + " it would come from.");
547	            }
548	            from.add(payment);
549	            parts.add(part);
550	            left = left.subtract(part);
551	        }
552	        if (left.signum() > 0) {
553	            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of $"
554	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString() + ".");
555	        }
556	        for (int i = 0; i < from.size(); i++) {
557	            Payment payment = from.get(i);
558	            payment.refund(parts.get(i));
559	            payments.saveAndFlush(payment);
560	            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
561	                    + parts.get(i).setScale(2, RoundingMode.UNNECESSARY).toPlainString());
562	        }
563	        return Optional.of(clientId);
564	    }
