615	    /** The date each fully paid invoice was paid (see {@link Invoice#paidOn}); an invoice not fully paid is left out. */
616	    @Transactional(readOnly = true)
617	    public Map<Long, LocalDate> paidOn(List<Invoice> list) {
618	        Map<Long, LocalDate> paidOn = new HashMap<>();
619	        if (list.isEmpty()) {
620	            return paidOn;
621	        }
622	        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
623	        BigDecimal rate = taxRate.percent();
624	        for (Invoice i : list) {
625	            LocalDate on = i.paidOn(found, rate);
626	            if (on != null) {
627	                paidOn.put(i.getId(), on);
628	            }
