633	    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
634	    @Transactional(readOnly = true)
635	    public Map<Long, BigDecimal> paid(List<Invoice> list) {
636	        Map<Long, BigDecimal> paid = new HashMap<>();
637	        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
638	        if (!list.isEmpty()) {
639	            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
640	                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
641	            }
642	        }
643	        return paid;
