646	    /**
647	     * Records a payment of the amount on the date against a sent invoice that still has something
648	     * due, and records it in the audit; empty if no such invoice. The amount has already been
649	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
650	     * invoice already paid, or a date after today
651	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
652	     * already been checked; one that belongs to a different invoice is refused.
653	     */
654	    @Transactional
655	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
656	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
657	        found.ifPresent(invoice -> {
658	            if (invoice.isDraft()) {
659	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
660	            }
661	            if (invoice.isVoid()) {
662	                throw new InvoiceRejectedException("A void invoice takes no payments.");
663	            }
664	            if (invoice.isCreditNote()) {
665	                throw new InvoiceRejectedException("A credit note takes no payments.");
666	            }
667	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
668	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
669	            if (due.signum() <= 0) {
670	                throw new InvoiceRejectedException("This invoice has already been paid.");
671	            }
672	            BigDecimal applied = amount.min(due);
673	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
674	                throw new InvoiceRejectedException("A part payment must be at least $"
675	                        + invoice.minimumPart(taxRate.percent()).toPlainString()
676	                        + " (10% of the total), unless it settles the invoice.");
677	            }
678	            LocalDate now = today.date();
679	            if (date.isAfter(now)) {
680	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
681	            }
682	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
683	                throw new InvoiceRejectedException(
684	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
685	            }
686	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
687	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
688	                        + " is the reference of a different invoice; this invoice's is "
689	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
690	            }
691	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference));
692	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
693	                    + applied.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
694	            recordWriteOff(invoice);
695	            recordCreditHeld(payment);
696	        });
697	        return found;
698	    }
699	
700	    /**
701	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
702	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
703	     * paying each off in full before the next.
704	     * What it pays beyond everything the client owes is held on the client's account as credit; the
705	     * rest is checked and recorded as a split payment over the invoices it reaches.
706	     * References (empty when none, each already checked) instead limit the payment to the client's
707	     * invoices with those references, applied in the same order; one that is not the reference of any
708	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
709	     * as credit.
710	     * The payment keeps the reference of the first invoice it reaches.
711	     */
712	    @Transactional
713	    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, List<String> references) {
714	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
715	        List<Invoice> candidates = ofClient;
716	        if (!references.isEmpty()) {
717	            Set<Long> named = new HashSet<>();
718	            for (String reference : references) {
719	                Invoice invoice = ofClient.stream()
720	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
721	                        .findFirst()
722	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
723	                                + " is not the reference of any of this client's invoices."));
724	                String number = InvoiceNumber.of(invoice.getId());
725	                if (invoice.isDraft()) {
726	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
727	                }
728	                if (invoice.isVoid()) {
729	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
730	                }
731	                if (invoice.isCreditNote()) {
732	                    throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
733	                }
734	                named.add(invoice.getId());
735	            }
736	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
737	        }
738	        List<Invoice> sent = candidates.stream()
739	                .filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote())
740	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
741	                        .thenComparing(Invoice::getId))
742	                .toList();
743	        Map<Long, BigDecimal> paid = paid(sent);
744	        BigDecimal owed = BigDecimal.ZERO;
745	        BigDecimal left = amount;
746	        List<PaymentAllocation> parts = new ArrayList<>();
747	        for (Invoice invoice : sent) {
748	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
749	            if (due.signum() <= 0) {
750	                continue;
751	            }
752	            owed = owed.add(due);
753	            if (left.signum() > 0) {
754	                BigDecimal part = left.min(due);
755	                parts.add(new PaymentAllocation(invoice.getId(), part));
756	                left = left.subtract(part);
757	            }
758	        }
759	        if (owed.signum() <= 0) {
760	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
761	                    : "Those invoices have already been paid.");
762	        }
763	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
764	        return recordSpread(clientId, amount, date, reference, parts, true);
765	    }
766	
767	    /**
768	     * Records one payment of the amount on the date spread over several of the client's invoices, and
769	     * records each part in the audit. The amounts have already been checked to be more than zero; they
770	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
771	     * and be no more than what it still has due. The date must be no later than today nor before any
772	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
773	     * be the reference of one of the invoices.
774	     */
775	    @Transactional
776	    public Payment recordSplitPayment(Long clientId, BigDecimal amount, LocalDate date, String reference,
777	            List<PaymentAllocation> parts) {
778	        return recordSpread(clientId, amount, date, reference, parts, false);
779	    }
780	
781	    /**
782	     * Records the payment spread over the parts as {@link #recordSplitPayment} does, except that when
783	     * credit may be held the parts may add up to less than the payment: the rest is held on the
784	     * client's account as credit and recorded in the audit.
785	     */
786	    private Payment recordSpread(Long clientId, BigDecimal amount, LocalDate date, String reference,
787	            List<PaymentAllocation> parts, boolean holdCredit) {
788	        if (parts.isEmpty()) {
789	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
790	        }
791	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
792	        if (holdCredit ? sum.compareTo(amount) > 0 : sum.compareTo(amount) != 0) {
793	            throw new InvoiceRejectedException("The amounts for the invoices add up to $"
794	                    + sum.setScale(2).toPlainString() + ", not the $" + amount.setScale(2).toPlainString() + " paid.");
795	        }
796	        LocalDate now = today.date();
797	        if (date.isAfter(now)) {
798	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
799	        }
800	        Set<Long> seen = new HashSet<>();
801	        List<Invoice> spreadOver = new ArrayList<>();
802	        for (PaymentAllocation part : parts) {
803	            if (!seen.add(part.getInvoiceId())) {
804	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
805	            }
806	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
807	                    .filter(i -> i.getClientId().equals(clientId))
808	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
809	            String number = InvoiceNumber.of(invoice.getId());
810	            if (invoice.isDraft()) {
811	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
812	            }
813	            if (invoice.isVoid()) {
814	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
815	            }
816	            if (invoice.isCreditNote()) {
817	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
818	            }
819	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
820	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
821	            if (part.getAmount().compareTo(due) > 0) {
822	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
823	                        + number + " is more than the $" + due.toPlainString() + " it has due.");
824	            }
825	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
826	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
827	                        + number + " is less than $" + invoice.minimumPart(taxRate.percent()).toPlainString()
828	                        + " (10% of its total), unless it settles the invoice.");
829	            }
830	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
831	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
832	                        + " (" + invoice.getIssueDate() + ").");
833	            }
834	            spreadOver.add(invoice);
835	        }
836	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
837	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
838	                    + " is not the reference of any of the invoices being paid.");
839	        }
840	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts));
841	        for (PaymentAllocation part : parts) {
842	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
843	                    + part.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
844	        }
845	        spreadOver.forEach(this::recordWriteOff);
846	        recordCreditHeld(payment);
847	        return payment;
848	    }
849	
850	    /** Records in the audit what a payment just recorded holds on the client's account as credit, if anything. */
851	    private void recordCreditHeld(Payment payment) {
852	        BigDecimal credit = payment.credit();
853	        if (credit.signum() > 0) {
854	            audit.record("CREDIT_HELD payment=" + payment.getId() + " amount="
855	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
856	        }
857	    }
858	
859	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
860	    private void recordWriteOff(Invoice invoice) {
861	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
862	        if (writtenOff.signum() > 0) {
863	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + writtenOff.toPlainString());
864	        }
865	    }
866	
867	    /**
868	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
869	     * records it in the audit; empty if no such payment. A payment already reversed, or one that has
870	     * had any of its credit refunded, or credit from a credit note, is refused.
871	     */
872	    @Transactional
873	    public Optional<Payment> reversePayment(Long paymentId) {
874	        Optional<Payment> found = payments.findById(paymentId);
875	        found.ifPresent(payment -> {
876	            if (payment.isReversed()) {
877	                throw new InvoiceRejectedException("This payment has already been reversed.");
878	            }
879	            if (payment.getCreditNote() != null) {
880	                throw new InvoiceRejectedException("This is credit from a credit note, so it cannot be reversed.");
881	            }
882	            if (payment.getRefunded().signum() > 0) {
883	                throw new InvoiceRejectedException("This payment has had credit refunded, so it cannot be reversed.");
884	            }
885	            payment.reverse();
886	            payments.saveAndFlush(payment);
887	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
888	                    + payment.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
889	        });
890	        return found;
891	    }
892	}
